def factorize(n: int) -> List[int]:
    def prime_factors(num):
        factors = []
        divisor = 2
        while divisor <= num:
            if num % divisor == 0:
                factors.append(divisor)
                num = num / divisor
            else:
                divisor += 1
        return factors

    def count_occurrences(factors):
        occurrences = {}
        for factor in factors:
            if factor in occurrences:
                occurrences[factor] += 1
            else:
                occurrences[factor] = 1
        return occurrences

    all_factors = prime_factors(n)
    occurrences = count_occurrences(all_factors)

    result = []
    for factor, count in occurrences.items():
        result.extend([factor] * count)

    return result

